pub const QRP_IDENTIFIER: &str = "$QRP";

#[inline]
pub fn qrp_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, QRP_IDENTIFIER, false)
}

